static int sandbox_i2c_rtc_prepare_read ( struct udevice * emul ) { struct sandbox_i2c_rtc_plat_data * plat = dev_get_plat ( emul ) ; struct rtc_time time ; int ret ; if ( ret ) { return ret ; } plat -> reg [ REG_SEC ] = time . tm_sec ; plat -> reg [ REG_MIN ] = time . tm_min ; plat -> reg [ REG_HOUR ] = time . tm_hour ; plat -> reg [ REG_MDAY ] = time . tm_mday ; plat -> reg [ REG_MON ] = time . tm_mon ; plat -> reg [ REG_YEAR ] = time . tm_year - 1900 ; plat -> reg [ REG_WDAY ] = time . tm_wday ; return 0 ; } 